"""Project the implemented family declarations into catalog metadata and borrowed C++ tables."""

from __future__ import annotations

import json
from typing import TYPE_CHECKING, Any

from parameter_values import invalid

if TYPE_CHECKING:
    from pathlib import Path

PREAMBLE = (
    "// SPDX-FileCopyrightText: 2026 Ervins Strauhmanis\n"
    "// SPDX-License-Identifier: MPL-2.0\n"
    "// Generated by tools/generate_spec.py from spec/method-contract.json.\n"
    "#pragma once\n"
    '#include "docenhance/methods/catalog.hpp"\n\n'
    "#include <array>\nnamespace docenhance::methods {\n"
)


def catalog_entries(
    families: list[dict[str, Any]], options: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    """One entry per implemented type; automatic selectors do not invent another capability."""
    by_name = {option["name"]: option for option in options}
    entries = []
    canonical: set[str] = set()
    for family in sorted(families, key=lambda item: item["order"]):
        for method in sorted(family["methods"], key=lambda item: item["id"]):
            selectors = list(method["selectors"])
            explicit = [
                name
                for name, value in method["selectors"].items()
                if value.get("mode", "explicit") == "explicit"
            ]
            primary = explicit[0] if explicit else selectors[0]
            if primary in canonical:
                invalid(f"{method['id']}: colliding canonical C++ descriptor")
            canonical.add(primary)
            parameters = [by_name[p["option"]] for p in [*family["shared"], *method["parameters"]]]
            entries.append(
                {
                    "id": method["id"],
                    "method_version": method["version"],
                    "selector": primary,
                    "selectors": selectors,
                    "name": method["name"],
                    "family": family["family"],
                    "parameters": parameters,
                }
            )
    return entries


def parameter_projection(parameter: dict[str, Any]) -> dict[str, str]:
    """Expose a user's option/domain, without internal C++ resource-binding field names."""
    return {
        "option": parameter["name"],
        "kind": parameter["kind"],
        "domain": parameter["domain"],
        "description": parameter["summary"],
    }


def catalog_projection(entry: dict[str, Any]) -> dict[str, Any]:
    """Discovery has richer entries; persistent v14 method identities stay id/version only."""
    return {
        **{key: entry[key] for key in ("id", "method_version", "name", "family", "selectors")},
        "parameters": [parameter_projection(parameter) for parameter in entry["parameters"]],
    }


def metadata_headers(root: Path, entries: list[dict[str, Any]]) -> dict[Path, str]:
    """Keep human parameter metadata separate from numeric domains to respect source size bounds."""
    parameters: dict[str, dict[str, Any]] = {}
    for entry in entries:
        for parameter in entry["parameters"]:
            parameters.setdefault(parameter["name"], parameter)
    names = list(parameters)
    text = (
        PREAMBLE
        + "inline constexpr auto parameter_descriptions = std::to_array<MethodParameter>({\n"
    )
    for parameter in parameters.values():
        text += (
            "    {"
            + ", ".join(
                f".{key} = {json.dumps(value, ensure_ascii=False)}"
                for key, value in parameter_projection(parameter).items()
            )
            + ",},\n"
        )
    text += "});\n} // namespace docenhance::methods\n"
    return {
        root / "include/docenhance/methods/method_parameter_metadata.hpp": text,
        root / "include/docenhance/methods/method_catalog.hpp": render_catalog(entries, names),
    }


def render_catalog(entries: list[dict[str, Any]], parameter_names: list[str]) -> str:
    """Borrow immutable metadata; C++ separately checks actual variant membership."""
    text = PREAMBLE.replace(
        '#include "docenhance/methods/catalog.hpp"',
        '#include "docenhance/methods/method_parameter_metadata.hpp"',
    )
    for entry in entries:
        primary = entry["selector"]
        text += f"inline constexpr auto {primary}_selectors = std::to_array<std::string_view>({{"
        text += ", ".join(json.dumps(value) for value in entry["selectors"]) + ",});\n"
        if entry["parameters"]:
            text += (
                f"inline constexpr auto {primary}_parameters = std::to_array<MethodParameter>({{"
            )
            text += (
                ", ".join(
                    f"std::get<{parameter_names.index(p['name'])}>(parameter_descriptions)"
                    for p in entry["parameters"]
                )
                + ",});\n"
            )
        text += f"inline constexpr ImplementedMethod {primary}_descriptor{{\n"
        for key in ("id", "method_version", "selector", "name", "family"):
            literal = (
                f"{entry[key]}U"
                if key == "method_version"
                else json.dumps(entry[key], ensure_ascii=False)
            )
            text += f"    .{key} = {literal},\n"
        text += f"    .selectors = {primary}_selectors,\n"
        text += (
            f"    .parameters = {primary}_parameters,\n"
            if entry["parameters"]
            else "    .parameters = {},\n"
        )
        text += "};\n"
    text += "inline constexpr auto declared_methods = std::to_array<ImplementedMethod>({\n"
    text += "".join(f"    {entry['selector']}_descriptor,\n" for entry in entries)
    return text + "});\n} // namespace docenhance::methods\n"
